export interface FactoryRunUsage {
  factoryRunUsageId: number;
  factoryRunRef: string;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  costUSD: number;
  modelName: string;
  timestamp: string;
  created_At: string;
  updated_at?: string;
}

export interface FactoryRunUsageListResponse {
  factoryRunUsages: FactoryRunUsage[];
}

// GET ALL — POST /all_factoryRunUsages
export async function getAllFactoryRunUsages(): Promise<FactoryRunUsage[]> {
  const res = await fetch(BASE_URL + "/all_factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{}] }), // No companyId, empty object for all
  });
  if (!res.ok) throw new Error((await res.text()) || 'Error fetching factory run usages');
  const data: FactoryRunUsageListResponse = await res.json();
  return data.factoryRunUsages ?? [];   // unwrap: SP wraps array under plural key
}

// GET ONE — POST /one_factoryRunUsages
export async function getFactoryRunUsageById(id: number): Promise<FactoryRunUsage | null> {
  const res = await fetch(BASE_URL + "/one_factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsageId": id }),
  });
  if (!res.ok) throw new Error((await res.text()) || 'Error fetching single factory run usage');
  const data: FactoryRunUsageListResponse = await res.json();
  return data.factoryRunUsages?.[0] ?? null;
}

// CREATE — action: 1
export async function createFactoryRunUsage(payload: Omit<FactoryRunUsage, "factoryRunUsageId" | "created_At" | "updated_at">): Promise<FactoryRunUsage> {
  const res = await fetch(BASE_URL + "/factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) throw new Error((await res.text()) || 'Error creating factory run usage');
  return await res.json();
}

// UPDATE — action: 2
export async function updateFactoryRunUsage(id: number, payload: Partial<Omit<FactoryRunUsage, "factoryRunUsageId" | "created_At" | "updated_at" | "timestamp">>): Promise<FactoryRunUsage> {
  const res = await fetch(BASE_URL + "/factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": 2, "factoryRunUsageId": id, ...payload }] }),
  });
  if (!res.ok) throw new Error((await res.text()) || 'Error updating factory run usage');
  return await res.json();
}

// DELETE — action: 3
export async function deleteFactoryRunUsage(id: number): Promise<void> {
  const res = await fetch(BASE_URL + "/factoryRunUsages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": 3, "factoryRunUsageId": id }] }),
  });
  if (!res.ok) throw new Error((await res.text()) || 'Error deleting factory run usage');
}
