    "content": "import React, { useState, useEffect, useRef } from 'react';
import { IonPage, IonContent, IonHeader, IonToolbar, IonTitle, IonButton, IonList, IonItem, IonLabel, IonModal, IonInput, IonText, IonLoading, IonToast, IonFab, IonFabButton, IonIcon, IonAlert, useIonViewWillEnter, IonSearchbar, IonInfiniteScroll, IonInfiniteScrollContent } from '@ionic/react';
import { addOutline, createOutline, trashOutline, searchOutline, closeOutline } from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../components/UserContext';
import {
  FactoryRunUsage,
  getAllFactoryRunUsages,
  createFactoryRunUsage,
  updateFactoryRunUsage,
  deleteFactoryRunUsage,
} from '../api/FactoryRunUsageApi';
import { SearchbarInputEventDetail } from '@ionic/core';
import { InputInputEventDetail } from '@ionic/core';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const FactoryRunUsagePage: React.FC = () => {
  const { roleCode } = useUser();
  const [factoryRunUsages, setFactoryRunUsages] = useState<FactoryRunUsage[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState<Partial<FactoryRunUsage>>({});
  const [searchText, setSearchText] = useState('');
  const [showAlert, setShowAlert] = useState(false);
  const [usageToDelete, setUsageToDelete] = useState<number | null>(null);

  // Infinite scroll state
  const [displayCount, setDisplayCount] = useState(20);
  const ITEMS_PER_LOAD = 20;

  const [popoverState, setPopoverState] = useState({
    showAlertPopover: false,
    showMailPopover: false,
    event: undefined as Event | undefined,
  });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const loadFactoryRunUsages = async () => {
    setLoading(true);
    setError('');
    try {
      const data = await getAllFactoryRunUsages();
      setFactoryRunUsages(data);
    } catch (err) {
      setError((err as Error).message ?? 'Error loading factory run usages');
    }
    setLoading(false);
  };

  useIonViewWillEnter(() => {
    loadFactoryRunUsages();
  });

  useEffect(() => {
    loadFactoryRunUsages();
  }, []);

  const filteredUsages = factoryRunUsages.filter(usage =>
    usage.factoryRunRef.toLowerCase().includes(searchText.toLowerCase()) ||
    usage.modelName.toLowerCase().includes(searchText.toLowerCase())
  );

  const displayedUsages = filteredUsages.slice(0, displayCount);

  const loadMoreItems = () => {
    setDisplayCount(prevCount => prevCount + ITEMS_PER_LOAD);
  };

  const handleCreateClick = () => {
    setIsEditing(false);
    setFormData({
      factoryRunRef: '',
      promptTokens: undefined,
      completionTokens: undefined,
      totalTokens: undefined,
      costUSD: undefined,
      modelName: '',
      timestamp: new Date().toISOString().slice(0, 16), // YYYY-MM-DDTHH:MM
    });
    setShowModal(true);
  };

  const handleEditClick = (usage: FactoryRunUsage) => {
    setIsEditing(true);
    setFormData({
      ...usage,
      costUSD: usage.costUSD !== undefined ? Number(usage.costUSD).toFixed(2) : undefined,
      // Ensure timestamp is in 'YYYY-MM-DDTHH:MM' format for IonInput type="datetime-local"
      timestamp: usage.timestamp ? new Date(usage.timestamp).toISOString().slice(0, 16) : new Date().toISOString().slice(0, 16),
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    setLoading(true);
    setError('');
    try {
      const payload = {
        ...formData,
        promptTokens: formData.promptTokens ? Number(formData.promptTokens) : 0,
        completionTokens: formData.completionTokens ? Number(formData.completionTokens) : 0,
        totalTokens: formData.totalTokens ? Number(formData.totalTokens) : 0,
        costUSD: formData.costUSD ? Number(formData.costUSD) : 0,
        timestamp: formData.timestamp ? new Date(formData.timestamp).toISOString() : new Date().toISOString(),
      };

      if (isEditing && formData.factoryRunUsageId) {
        await updateFactoryRunUsage(formData.factoryRunUsageId, payload);
      } else {
        await createFactoryRunUsage(payload as Omit<FactoryRunUsage, "factoryRunUsageId" | "created_At" | "updated_at">);
      }
      setShowModal(false);
      loadFactoryRunUsages();
    } catch (err) {
      setError((err as Error).message ?? 'Error saving factory run usage');
    }
    setLoading(false);
  };

  const handleDeleteClick = (id: number) => {
    setUsageToDelete(id);
    setShowAlert(true);
  };

  const confirmDelete = async () => {
    if (usageToDelete !== null) {
      setLoading(true);
      setError('');
      try {
        await deleteFactoryRunUsage(usageToDelete);
        loadFactoryRunUsages();
      } catch (err) {
        setError((err as Error).message ?? 'Error deleting factory run usage');
      }
      setLoading(false);
      setUsageToDelete(null);
    }
  };

  const handleInputChange = (e: CustomEvent<InputInputEventDetail>) => {
    const { name, value } = e.target as HTMLIonInputElement;
    setFormData({ ...formData, [name!]: value });
  };

  return (
    <IonPage className="factoryrunusage-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Uso de Ejecución de Fábrica — Factory AI GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          placeholder="Buscar por referencia o modelo"
          value={searchText}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchText(e.detail.value!)}
        />

        <IonList className="factoryrunusage-list">
          {displayedUsages.map(usage => (
            <IonItem key={usage.factoryRunUsageId} className="factoryrunusage-item">
              <IonLabel>
                <h2>Ref: {usage.factoryRunRef} - {usage.modelName}</h2>
                <p>Prompt Tokens: {usage.promptTokens}</p>
                <p>Completion Tokens: {usage.completionTokens}</p>
                <p>Total Tokens: {usage.totalTokens}</p>
                <p>Costo (USD): ${Number(usage.costUSD).toFixed(2)}</p>
                <p>Timestamp: {toHermosillo(usage.timestamp)}</p>
              </IonLabel>
              {roleCode === 'Admin' && (
                <div className="item-actions">
                  <IonButton fill="clear" color="primary" onClick={() => handleEditClick(usage)}>
                    <IonIcon icon={createOutline} />
                  </IonButton>
                  <IonButton fill="clear" color="danger" onClick={() => handleDeleteClick(usage.factoryRunUsageId)}>
                    <IonIcon icon={trashOutline} />
                  </IonButton>
                </div>
              )}
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll
          onIonInfinite={(ev: CustomEvent<void>) => {
            loadMoreItems();
            (ev.target as HTMLIonInfiniteScrollElement).complete();
          }}
          threshold="100px"
          disabled={displayCount >= filteredUsages.length}
        >
          <IonInfiniteScrollContent loadingText="Cargando más usos..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        {roleCode === 'Admin' && (
          <IonFab vertical="bottom" horizontal="end" slot="fixed">
            <IonFabButton onClick={handleCreateClick}>
              <IonIcon icon={addOutline} />
            </IonFabButton>
          </IonFab>
        )}

        <IonModal isOpen={showModal} onDidDismiss={() => setShowModal(false)}>
          <IonHeader>
            <IonToolbar>
              <IonTitle>{isEditing ? 'Editar Uso de Ejecución de Fábrica' : 'Nuevo Uso de Ejecución de Fábrica'}</IonTitle>
              <IonButton slot="end" fill="clear" onClick={() => setShowModal(false)}>
                <IonIcon icon={closeOutline} />
              </IonButton>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="factoryrunusage-form">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Referencia de Ejecución de Fábrica *"
                  labelPlacement="floating"
                  name="factoryRunRef"
                  value={formData.factoryRunRef}
                  onIonInput={handleInputChange}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre del Modelo *"
                  labelPlacement="floating"
                  name="modelName"
                  value={formData.modelName}
                  onIonInput={handleInputChange}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Tokens de Prompt *"
                  labelPlacement="floating"
                  type="number"
                  name="promptTokens"
                  value={formData.promptTokens}
                  onIonInput={handleInputChange}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Tokens de Finalización *"
                  labelPlacement="floating"
                  type="number"
                  name="completionTokens"
                  value={formData.completionTokens}
                  onIonInput={handleInputChange}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Tokens Totales *"
                  labelPlacement="floating"
                  type="number"
                  name="totalTokens"
                  value={formData.totalTokens}
                  onIonInput={handleInputChange}
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Costo (USD) *"
                  labelPlacement="floating"
                  type="number"
                  name="costUSD"
                  value={formData.costUSD}
                  onIonInput={handleInputChange}
                  step="0.01"
                  required
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Timestamp *"
                  labelPlacement="floating"
                  type="datetime-local"
                  name="timestamp"
                  value={formData.timestamp}
                  onIonInput={handleInputChange}
                  required
                />
              </div>
              <IonButton expand="block" onClick={handleSave} disabled={loading}>
                {loading ? <IonSpinner name="dots" /> : 'Guardar'}
              </IonButton>
            </div>
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={showAlert}
          onDidDismiss={() => setShowAlert(false)}
          header={'Confirmar Eliminación'}
          message={'¿Estás seguro de que quieres eliminar este registro de uso?'}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: confirmDelete }
          ]}
        />

        <IonLoading isOpen={loading} message={'Cargando...'}
        />

        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color="danger"
        />
      </IonContent>
    </IonPage>
  );
};

export default FactoryRunUsagePage;
